export default [{"w":"benefits","pos":"noun (plural)","def":"Money paid by the government to people who need financial help, for example if they are unemployed, disabled or on a low income.","defId":"Uang yang dibayarkan pemerintah kepada orang yang membutuhkan bantuan keuangan, misalnya karena menganggur, disabilitas, atau berpenghasilan rendah.","ex":"You may be able to claim benefits if your income is very low.","exId":"Anda mungkin bisa mengajukan tunjangan (benefits) jika penghasilan Anda sangat rendah.","colloc":["claim benefits","on benefits","housing benefit"],"theme":"uk_money"},{"w":"biometric residence permit","pos":"noun phrase","def":"An identity card, now largely replaced by an online eVisa, showing a foreign national's right to stay and work in the UK.","defId":"Kartu identitas, yang kini sebagian besar digantikan oleh eVisa daring, yang menunjukkan hak warga negara asing untuk tinggal dan bekerja di Inggris.","ex":"My biometric residence permit showed my visa status until it was replaced by an eVisa.","exId":"Biometric residence permit saya menunjukkan status visa saya sampai digantikan oleh eVisa.","colloc":["a biometric residence permit (BRP)","collect your biometric residence permit","your BRP expires"],"theme":"uk_money"},{"w":"contactless","pos":"adjective (also noun)","def":"A way of paying by tapping a card or phone on a reader, without entering a PIN.","defId":"Cara membayar dengan menempelkan kartu atau ponsel ke mesin pembaca, tanpa memasukkan PIN.","ex":"Just tap your card on the reader — most shops take contactless now.","exId":"Cukup tempelkan kartu Anda ke mesin — kebanyakan toko sekarang menerima pembayaran nirsentuh (contactless).","colloc":["pay contactless","a contactless payment","the contactless limit"],"theme":"uk_money"},{"w":"current account","pos":"noun phrase","def":"An everyday bank account used for receiving your wages and paying bills.","defId":"Rekening bank sehari-hari yang dipakai untuk menerima gaji dan membayar tagihan.","ex":"Your salary will be paid straight into your current account.","exId":"Gaji Anda akan dibayarkan langsung ke rekening giro (current account) Anda.","colloc":["open a current account","a joint current account","your current account"],"theme":"uk_money"},{"w":"HMRC","pos":"noun (abbreviation)","def":"His Majesty's Revenue and Customs — the UK government department that collects taxes.","defId":"His Majesty's Revenue and Customs — departemen pemerintah Inggris yang memungut pajak.","ex":"HMRC sent me a letter saying I'd paid too much tax and was due a refund.","exId":"HMRC mengirimi saya surat yang menyatakan bahwa saya membayar pajak terlalu banyak dan berhak mendapat pengembalian.","colloc":["contact HMRC","register with HMRC","an HMRC tax code"],"theme":"uk_money"},{"w":"invoice","pos":"noun","def":"A document that lists goods or services provided and asks for payment.","defId":"Dokumen yang merinci barang atau jasa yang diberikan dan meminta pembayaran.","ex":"I sent the client an invoice for the work and expect to be paid within 30 days.","exId":"Saya mengirim faktur (invoice) kepada klien atas pekerjaan itu dan berharap dibayar dalam 30 hari.","colloc":["send an invoice","pay an invoice","an outstanding invoice"],"theme":"uk_money"},{"w":"ISA","pos":"noun (abbreviation)","def":"Individual Savings Account — a savings or investment account on which you pay no tax on the interest or gains.","defId":"Individual Savings Account — rekening tabungan atau investasi yang bunga atau keuntungannya tidak dikenai pajak.","ex":"I put some money into a cash ISA because the interest is tax-free.","exId":"Saya menaruh sebagian uang di cash ISA karena bunganya bebas pajak.","colloc":["a cash ISA","open an ISA","pay into an ISA"],"theme":"uk_money"},{"w":"minimum wage","pos":"noun phrase","def":"The lowest hourly pay an employer is legally allowed to give a worker.","defId":"Upah per jam terendah yang secara hukum boleh diberikan pemberi kerja kepada pekerja.","ex":"By law, they must pay you at least the national minimum wage for every hour you work.","exId":"Menurut hukum, mereka harus membayar Anda setidaknya upah minimum nasional untuk setiap jam kerja.","colloc":["the national minimum wage","earn minimum wage","below the minimum wage"],"theme":"uk_money"},{"w":"National Insurance number","pos":"noun phrase","def":"A unique personal number used to record your tax and National Insurance contributions in the UK.","defId":"Nomor pribadi unik yang dipakai untuk mencatat pajak dan iuran jaminan sosial (National Insurance) Anda di Inggris.","ex":"You'll need your National Insurance number before you can start your new job.","exId":"Anda memerlukan nomor National Insurance sebelum bisa mulai bekerja di pekerjaan baru Anda.","colloc":["apply for a National Insurance number","quote your National Insurance number","a National Insurance number letter"],"theme":"uk_money"},{"w":"overdraft","pos":"noun","def":"An arrangement that lets you spend more money than you have in your bank account, up to an agreed limit.","defId":"Fasilitas yang membuat Anda bisa membelanjakan uang melebihi saldo di rekening bank, sampai batas yang disepakati.","ex":"I went into my overdraft at the end of the month and got charged interest.","exId":"Saya masuk ke saldo minus (overdraft) di akhir bulan dan dikenai bunga.","colloc":["go into your overdraft","an arranged overdraft","overdraft fees"],"theme":"uk_money"},{"w":"P45","pos":"noun","def":"A form your employer gives you when you leave a job, showing your pay and tax so far that year.","defId":"Formulir yang diberikan pemberi kerja saat Anda berhenti bekerja, yang menunjukkan gaji dan pajak Anda sepanjang tahun itu.","ex":"When you leave, they'll give you a P45 to hand to your next employer.","exId":"Saat Anda berhenti, mereka akan memberi Anda P45 untuk diserahkan ke pemberi kerja berikutnya.","colloc":["give you a P45","get your P45","a P45 form"],"theme":"uk_money"},{"w":"P60","pos":"noun","def":"A form summarising your total pay and tax for the whole tax year, given to you by your employer.","defId":"Formulir yang merangkum total gaji dan pajak Anda selama satu tahun pajak penuh, diberikan oleh pemberi kerja.","ex":"You'll get a P60 in April showing everything you earned and paid in tax last year.","exId":"Anda akan menerima P60 pada bulan April yang menunjukkan seluruh penghasilan dan pajak Anda tahun lalu.","colloc":["get your P60","a P60 form","keep your P60"],"theme":"uk_money"},{"w":"PAYE","pos":"noun (abbreviation)","def":"Pay As You Earn — the system by which employers deduct income tax and National Insurance from your wages before paying you.","defId":"Pay As You Earn — sistem yang membuat pemberi kerja memotong pajak penghasilan dan National Insurance dari gaji Anda sebelum membayarkannya.","ex":"Most employees pay tax automatically through PAYE, so they never file a tax return.","exId":"Sebagian besar karyawan membayar pajak secara otomatis melalui PAYE, sehingga tidak perlu mengajukan tax return.","colloc":["pay tax through PAYE","the PAYE system","on PAYE"],"theme":"uk_money"},{"w":"payroll","pos":"noun","def":"The system or department that works out and pays employees' wages.","defId":"Sistem atau bagian yang menghitung dan membayar gaji karyawan.","ex":"If your bank details change, let payroll know so your wages go to the right account.","exId":"Jika detail rekening Anda berubah, beri tahu bagian penggajian (payroll) agar gaji Anda masuk ke rekening yang benar.","colloc":["on the payroll","the payroll department","run payroll"],"theme":"uk_money"},{"w":"payslip","pos":"noun","def":"A document from your employer showing your pay and the deductions taken from it.","defId":"Dokumen dari pemberi kerja yang menunjukkan gaji Anda dan potongan-potongan yang diambil darinya.","ex":"Check your payslip to see how much tax and National Insurance you've paid this month.","exId":"Periksa slip gaji (payslip) Anda untuk melihat berapa pajak dan National Insurance yang telah Anda bayar bulan ini.","colloc":["check your payslip","a monthly payslip","keep your payslips"],"theme":"uk_money"},{"w":"probation period","pos":"noun phrase","def":"A trial period at the start of a new job during which either side can end the employment more easily.","defId":"Masa percobaan di awal pekerjaan baru, saat kedua pihak dapat mengakhiri hubungan kerja dengan lebih mudah.","ex":"I passed my three-month probation period and now I'm a permanent member of staff.","exId":"Saya lulus masa percobaan (probation period) tiga bulan dan sekarang menjadi staf tetap.","colloc":["pass your probation period","a three-month probation period","during your probation period"],"theme":"uk_money"},{"w":"receipt","pos":"noun","def":"A printed or digital note proving you have paid for something.","defId":"Bukti tercetak atau digital yang menunjukkan Anda telah membayar sesuatu.","ex":"Keep the receipt in case you need to return the jacket.","exId":"Simpan struk (receipt) itu untuk berjaga-jaga jika Anda perlu mengembalikan jaketnya.","colloc":["keep the receipt","ask for a receipt","a till receipt"],"theme":"uk_money"},{"w":"refund","pos":"noun","def":"Money that is paid back to you, for example when you return goods or overpay.","defId":"Uang yang dikembalikan kepada Anda, misalnya saat Anda mengembalikan barang atau membayar lebih.","ex":"I took the faulty kettle back to the shop and got a full refund.","exId":"Saya mengembalikan ketel yang rusak ke toko dan mendapat pengembalian (refund) penuh.","colloc":["get a refund","a full refund","claim a refund"],"theme":"uk_money"},{"w":"right to work","pos":"noun phrase","def":"Legal permission to take paid employment in the UK.","defId":"Izin resmi untuk bekerja secara berbayar di Inggris.","ex":"Before you start, your employer must check that you have the right to work in the UK.","exId":"Sebelum Anda mulai, pemberi kerja harus memeriksa bahwa Anda memiliki hak untuk bekerja (right to work) di Inggris.","colloc":["right to work in the UK","a right to work check","prove your right to work"],"theme":"uk_money"},{"w":"salary","pos":"noun","def":"A fixed amount of money paid to an employee each year, usually in equal monthly instalments.","defId":"Jumlah uang tetap yang dibayarkan kepada karyawan setiap tahun, biasanya dalam cicilan bulanan yang sama besar.","ex":"The job has a starting salary of £28,000 a year, paid monthly.","exId":"Pekerjaan itu memiliki gaji awal £28.000 per tahun, dibayar bulanan.","colloc":["a starting salary","an annual salary","a salary of"],"theme":"uk_money"},{"w":"self-assessment","pos":"noun","def":"The HMRC system by which people with untaxed income calculate and report their own tax.","defId":"Sistem HMRC yang membuat orang dengan penghasilan yang belum dipotong pajak menghitung dan melaporkan pajaknya sendiri.","ex":"If you're self-employed, you pay your tax through self-assessment.","exId":"Jika Anda bekerja mandiri, Anda membayar pajak melalui sistem self-assessment.","colloc":["a self-assessment tax return","register for self-assessment","the self-assessment deadline"],"theme":"uk_money"},{"w":"sort code","pos":"noun phrase","def":"A six-digit number that identifies your bank and branch in the UK.","defId":"Nomor enam digit yang mengidentifikasi bank dan cabang Anda di Inggris.","ex":"To receive the payment, give them your account number and sort code.","exId":"Untuk menerima pembayaran, berikan mereka nomor rekening dan sort code Anda.","colloc":["your sort code","account number and sort code","a six-digit sort code"],"theme":"uk_money"},{"w":"tax return","pos":"noun phrase","def":"An official form on which you report your income to HMRC so they can work out how much tax you owe.","defId":"Formulir resmi untuk melaporkan penghasilan Anda kepada HMRC agar mereka dapat menghitung berapa pajak yang harus Anda bayar.","ex":"As a freelancer, I have to file a tax return every year by 31 January.","exId":"Sebagai pekerja lepas, saya harus mengajukan surat pemberitahuan pajak (tax return) setiap tahun paling lambat 31 Januari.","colloc":["file a tax return","submit a tax return","complete your tax return"],"theme":"uk_money"},{"w":"Universal Credit","pos":"noun phrase","def":"A monthly benefit payment for people on a low income or out of work, which replaces several older benefits.","defId":"Tunjangan bulanan bagi orang berpenghasilan rendah atau yang tidak bekerja, yang menggantikan beberapa tunjangan lama.","ex":"When she lost her job, she claimed Universal Credit to help with the rent.","exId":"Ketika kehilangan pekerjaan, dia mengajukan Universal Credit untuk membantu membayar sewa.","colloc":["claim Universal Credit","a Universal Credit payment","apply for Universal Credit"],"theme":"uk_money"},{"w":"visa","pos":"noun","def":"An official permission, usually in or linked to your passport, that lets you enter, stay or work in the UK.","defId":"Izin resmi, biasanya di dalam atau terkait paspor Anda, yang membuat Anda dapat masuk, tinggal, atau bekerja di Inggris.","ex":"Her work visa allows her to stay in the UK for five years.","exId":"Visa kerjanya memperbolehkannya tinggal di Inggris selama lima tahun.","colloc":["apply for a visa","a work visa","your visa expires"],"theme":"uk_money"},{"w":"workplace pension","pos":"noun phrase","def":"A pension scheme set up by your employer, into which both you and the employer usually pay.","defId":"Program pensiun yang dibentuk oleh pemberi kerja, yang biasanya diisi oleh Anda dan pemberi kerja.","ex":"You'll be automatically enrolled in a workplace pension, with money taken from each payslip.","exId":"Anda akan otomatis didaftarkan dalam pensiun dari tempat kerja (workplace pension), dengan uang yang dipotong dari setiap slip gaji.","colloc":["a workplace pension","auto-enrolment into a workplace pension","pay into a workplace pension"],"theme":"uk_money"},{"w":"zero-hours contract","pos":"noun phrase","def":"An employment contract that does not guarantee any set number of working hours.","defId":"Kontrak kerja yang tidak menjamin jumlah jam kerja tertentu.","ex":"On a zero-hours contract, some weeks I get plenty of shifts and other weeks none at all.","exId":"Dengan kontrak nol jam (zero-hours contract), ada minggu saat saya dapat banyak sif dan minggu lain tidak sama sekali.","colloc":["on a zero-hours contract","offer a zero-hours contract","zero-hours workers"],"theme":"uk_money"}];
